// Post-deploy verification for the bcba-program function. Fails closed on ANY mismatch.
// Usage: node verify-deployed-bcba.mjs <root> <deployed-function-dir>
//   <root>                  repo project root (navara-site) holding the committed artifacts
//   <deployed-function-dir> fresh CLI readback of the deployed function
// Checks: (1) deployed generated-bcba-bundle.mjs is byte-identical to the committed
// artifact; (2) deployed composition imports the NEW generated file and NOT the old
// CANDIDATE; (3) import-level equivalence of deployed vs committed generated bundles;
// (4) every member pin of the RETAINED old CANDIDATE is still served (no substitution);
// (5) the retained CANDIDATE file is present in the repo with its registry-pinned sha.
import fs from 'node:fs';
import path from 'node:path';
import { pathToFileURL } from 'node:url';
import { deepStrictEqual } from 'node:assert/strict';
import { sha256, loadBundles } from './lib-bundles.mjs';

const [rootArg, depArg] = process.argv.slice(2);
if (!rootArg || !depArg) { console.error('usage: verify-deployed-bcba.mjs <root> <deployed-function-dir>'); process.exit(2); }
const root = path.resolve(rootArg), dep = path.resolve(depArg);
const fail = m => { console.error('FAIL: ' + m); process.exit(1); };

// (1) deployed generated bytes == committed generated bytes
const committedGen = path.join(root, 'supabase', 'functions', 'bcba-program', 'generated-bcba-bundle.mjs');
const deployedGen = path.join(dep, 'generated-bcba-bundle.mjs');
for (const p of [committedGen, deployedGen]) if (!fs.existsSync(p)) fail('missing file ' + p);
const cb = fs.readFileSync(committedGen), db = fs.readFileSync(deployedGen);
if (sha256(cb) !== sha256(db)) fail(`deployed generated file sha ${sha256(db)} != committed ${sha256(cb)} - deploy did not ship the reviewed artifact`);
console.log('1 PASS deployed generated bytes == committed (' + sha256(cb) + ')');

// (2) composition import wiring - comment-aware: a path mentioned inside a comment is
// not an import, and a commented-out import is not wiring. Parse the comment-stripped
// source for actual import statements.
const compPath = path.join(dep, 'bcba-composition.mjs');
if (!fs.existsSync(compPath)) fail('deployed composition missing: ' + compPath);
const comp = fs.readFileSync(compPath, 'utf8');
const stripped = comp.replace(/\/\*[\s\S]*?\*\//g, ' ').replace(/(^|[^:'"])\/\/[^\n]*/g, '$1');
if (/import\s[^;]*?from\s*['"][^'"]*generated-bcba-bundle-CANDIDATE\.mjs['"]/.test(stripped)) fail('deployed composition still imports the old CANDIDATE file');
if (!/import\s[^;]*?from\s*['"]\.\/generated-bcba-bundle\.mjs['"]/.test(stripped)) fail('deployed composition does not import ./generated-bcba-bundle.mjs');
console.log('2 PASS composition imports ./generated-bcba-bundle.mjs (no CANDIDATE import)');

// (3) import-level equivalence deployed vs committed
const a = await loadBundles(pathToFileURL(committedGen).href);
const b = await loadBundles(pathToFileURL(deployedGen).href);
if (a.length !== b.length) fail('deployed vs committed bundle count mismatch');
for (let i = 0; i < a.length; i++) deepStrictEqual(b[i], a[i]);
console.log('3 PASS deployed generated bundles deep-equal committed (' + a.length + ' bundle(s))');

// (4) retained old member pins still served (no substitution at deploy)
const retained = path.join(root, 'release-retention', 'generated-bcba-bundle-CANDIDATE.mjs');
if (!fs.existsSync(retained)) fail('retained CANDIDATE missing from repo: ' + retained);
const oldObjs = await loadBundles(pathToFileURL(retained).href);
const newByPin = new Map(b.map(o => [o.policyId + '|' + o.manifestVersion, o]));
for (const o of oldObjs) {
  const got = newByPin.get(o.policyId + '|' + o.manifestVersion);
  if (!got) fail('deployed function no longer serves retained member pin ' + o.policyId + '|' + o.manifestVersion);
  deepStrictEqual(got, o);
}
console.log('4 PASS all ' + oldObjs.length + ' retained member pin(s) still served identically');

// (5) retained CANDIDATE sha matches the registry pin (retained forever)
const reg = JSON.parse(fs.readFileSync(path.join(root, 'release-retention', 'registry.json')));
const entry = (reg.bundles || []).find(x => x.file === 'generated-bcba-bundle-CANDIDATE.mjs');
if (!entry) fail('registry has no entry for the retained CANDIDATE');
if (sha256(fs.readFileSync(retained)) !== entry.sha256) fail('retained CANDIDATE bytes diverge from its registry pin');
console.log('5 PASS retained CANDIDATE bytes match registry pin ' + entry.sha256);
console.log('DEPLOY VERIFIED');
